import { create } from 'zustand'
import {
  inferKeyOf,
  queryKeyOfQuestion,
  type InferPathRaw,
} from './inferPath'
import {
  deliveryId,
  type DeskDeliveryLink,
} from './deskDelivery'

export type KeyKind = 'query' | 'brief' | 'book' | 'delta' | 'infer' | 'other'

/**
 * 主推理边：bookKey──(inferKey)──bookKey
 * inferKey = rationale 落账（类 briefKey）；UI 中桥，点开 = 左 in｜右 out 哈希异同
 */
export interface InferEdge {
  id: string
  inferKey: string
  /** 本步全部材料门（≥1；单门独自 / 二元 / 并肩） */
  bookKeys: string[]
  /** UI 连线端：单门时 from===to；多门时为首尾 */
  fromBookKey: string
  toBookKey: string
  rationale: string
  /** 哈希窗左（in）：材料摘录 + Q */
  leftText: string
  /** 哈希窗右（out）：本步 rationale */
  rightText: string
  question: string
  /** 路径回指成立后才有；settle 时一并铸 */
  queryKey: string
  pathIndex: number
  stepIndex: number
  /**
   * 落账时序序号（单调递增）。
   * 只标记进 LTM 的次序，便于查看/撤销；≠ 已调度进 WM，≠ 已钉注意力。
   */
  settleSeq: number
  createdAt: number
}

/** 现 queryKey ──增量边──► 旧 queryKey（复用采纳） */
export interface QueryReuseLink {
  id: string
  fromQueryKey: string
  toQueryKey: string
  question: string
  oldQuestion: string
  rationale: string
  /** 被采纳路径上的 inferKey */
  inferKeys: string[]
  /** 复用落账时序序号（与 InferEdge.settleSeq 同一计数器） */
  settleSeq: number
  createdAt: number
}

