/** bookKey → 曾用过的提问原文（倒查排除问法） */
function latestQueryKeyForQuestion(
  settled: Record<string, string>,
  question: string,
): string | null {
  const q = question.trim()
  if (!q) return null
  let best: string | null = null
  for (const [qk, text] of Object.entries(settled)) {
    if (text === q) best = qk
  }
  return best
}

