      const toBookKey = keys[keys.length - 1]!
      const rationale = step.rationale.trim()
      const { settleActionId, inferKey } = mintInferKey()
      const materialBlocks = keys.map((bk, i) => {
        const label =
          keys.length === 1
            ? '单门 · 原文'
            : keys.length === 2
              ? `bookKey ${i === 0 ? 'A' : 'B'} · 原文`
              : `bookKey[${i}] · 原文`
        const T = (bookTexts[bk] ?? '').slice(0, 400)
