export function parseDecideOutcome(llmText: string): {
  briefKeys: string[]
  keeps: Array<{ briefKey: string; prospect: string }>
  lastBriefKey: string | null
  coverage: string | null
  stopReason: string | null
  seedRange: SeedRange | null
  ok: boolean
  note: string
} {
  const obj = extractJsonObject(llmText)
  if (!obj || typeof obj !== 'object') {
    return {
      briefKeys: [],
      keeps: [],
      lastBriefKey: null,
      coverage: null,
      stopReason: null,
      seedRange: null,
      ok: false,
      note: 'decide 硬闸：无法解析 JSON',
    }
  }
  const root = obj as Record<string, unknown>
  const lastBriefKey = String(root.lastBriefKey ?? '').trim() || null
  const coverageRaw = String(root.coverage ?? '').trim()
  const coverage = coverageRaw ? normalizeDecideCoverage(coverageRaw) : null
  const stopReason = String(root.stopReason ?? '').trim() || null
  const seedRange = parseSeedRange(root.seedRange)
  const keep = root.keep
  const briefKeys: string[] = []
  const keeps: Array<{ briefKey: string; prospect: string }> = []
  if (Array.isArray(keep)) {
    for (const row of keep) {
      if (!row || typeof row !== 'object') continue
      const r = row as {
        briefKey?: unknown
        rationale?: unknown
        prospect?: unknown
      }
      const bk = String(r.briefKey ?? '').trim()
      if (!bk) continue
      briefKeys.push(bk)
      const prospect = String(r.prospect ?? r.rationale ?? '').trim()
      if (prospect) keeps.push({ briefKey: bk, prospect })
    }
  }
  if (!lastBriefKey || !coverage) {
    return {
      briefKeys: [...new Set(briefKeys)],
      keeps,
      lastBriefKey,
      coverage,
      stopReason,
      seedRange,
      ok: false,
      note: 'decide 硬闸：缺少 lastBriefKey 或 coverage（M1 必须有）',
    }
  }
  return {
    briefKeys: [...new Set(briefKeys)],
    keeps,
    lastBriefKey,
    coverage,
    stopReason,
    seedRange,
    ok: true,
    note: `decide · coverage=${coverage}` +
      (stopReason ? ` · stop=${stopReason}` : '') +
      (seedRange ? ` · seedRange` : '') +
      (keeps.length ? ` · prospect×${keeps.length}` : ''),
  }
}

