}

/**
 * 复用闸：主坐标 = pathKey + 展开(infer∥prospect)；能则现 qk ──reuse──► pathKey。
 */
export async function runReuseGate(input: {
  qNow: string
  bookKeys: string[]
  queryKey?: string
  onProgress?: (msg: string) => void
}): Promise<{
  adopted: boolean
  queryKey?: string
  reuseKey?: string
  pathKey?: string
  oldQueryKey?: string
  inferKeys?: string[]
  prospectKeys?: string[]
  judgments: ReturnType<typeof parseReuseJudgments>
  /** 玩法 A 排除：失败 path → 旧 qk + Q 原文 */
  excludeQuestions: Array<{ queryKey: string; qText: string }>
  raw: string
  note: string
}> {
  const paths = listCandidatePaths(input.bookKeys)
  if (paths.length === 0) {
    return {
      adopted: false,
      judgments: [],
      excludeQuestions: [],
      raw: '',
      note: '复用闸：无候选 pathKey（需先有 infer×prospect 匹配）',
    }
  }

  const st = useAttentionIo.getState()
  const settled = st.settledQueries
  const lines: string[] = [
    `Q_now：${input.qNow}`,
    '',
    '【候选 path · 每条以 pathKey 为主坐标；展开 = infer ∥ prospect】',
  ]
  for (const p of paths) {
    const edge = st.inferEdges.find((e) => e.inferKey === p.inferKey)
    const prospect = st.prospects.find((x) => x.prospectKey === p.prospectKey)
    lines.push(`\npathKey=\`${p.pathKey}\``)
    lines.push(`挂靠旧 queryKey=\`${p.queryKey}\``)
    lines.push(`旧 Q：${settled[p.queryKey] ?? edge?.question ?? '（无原文）'}`)
    lines.push(`inferKey=\`${p.inferKey}\``)
    lines.push(`ι 展开：${edge?.rationale ?? '（无）'}`)
    lines.push(`prospectKey=\`${p.prospectKey}\` · briefKey=\`${prospect?.briefKey ?? '?'}\``)
    lines.push(`prospect 展开：${prospect?.text ?? '（无）'}`)
  }
  lines.push(
    '\n请判断：哪条 path 能否解决 Q_now。\n' +
      '只输出 JSON：\n' +
      '{\n' +
      '  "judgments": [\n' +
      '    { "pathKey": "ph_…", "canSolve": true|false, "rationale": "依据…" }\n' +
      '  ]\n' +
      '}\n' +
      '规则：每个候选 pathKey 一条；主坐标是 pathKey（展开 infer∥prospect）；' +
      'canSolve=true 表示可复用、不必新开主推理；禁止以正文指纹当门牌。',
  )

  input.onProgress?.('写信台 · 复用闸 · LLM…')
  const chat = await flashChat({
    system: [
      '你是复用闸：只评「已有 path（infer×prospect）能否返回 / 撑住 Q_now」。',
      '主坐标是 pathKey；不写新路径；不改契约；不翻库；不靠正文指纹撞车。',
    ].join('\n'),
    user: lines.join('\n'),
    temperature: 0.1,
  })
  if (!chat.ok) {
    return {
      adopted: false,
      judgments: [],
      excludeQuestions: [],
      raw: '',
      note: `复用闸失败：${chat.note}`,
    }
  }

  let judgments = parseReuseJudgments(chat.content)
  if (judgments.length === 0 && /true|canSolve|能|不能|复用/i.test(chat.content)) {
    const hitTrue = /canSolve\s*[:=]\s*true|能解决|可以复用|足以回/i.test(
      chat.content,
    )
    judgments = paths.map((p, i) => ({
      pathKey: p.pathKey,
      inferKey: p.inferKey,
      canSolve: hitTrue && i === 0,
      rationale: chat.content.trim().slice(0, 400),
    }))
  }

  const byPath = new Map(paths.map((p) => [p.pathKey, p]))
  const failedQs = new Map<string, string>()
  for (const j of judgments) {
    if (j.canSolve) continue
    const path = byPath.get(j.pathKey) || paths.find((p) => p.inferKey === j.inferKey)
    if (!path) continue
    const qText = settled[path.queryKey] ?? ''
    if (qText.trim()) failedQs.set(path.queryKey, qText)
  }
  for (const p of paths) {
    if (judgments.some((j) => j.pathKey === p.pathKey || j.inferKey === p.inferKey))
      continue
    const qText = settled[p.queryKey] ?? ''
    if (qText.trim()) failedQs.set(p.queryKey, qText)
  }
  const excludeQuestions = [...failedQs.entries()].map(([queryKey, qText]) => ({
    queryKey,
    qText,
  }))

  const win = judgments.find((j) => j.canSolve)
  if (!win) {
    return {
      adopted: false,
      judgments,
      excludeQuestions,
      raw: chat.content,
      note: `复用闸：全部不够 · ${judgments.length} 条审过 → mainInfer 玩法 A`,
    }
  }

  const winPath =
    byPath.get(win.pathKey) ||
    paths.find((p) => p.inferKey === win.inferKey)
  if (!winPath) {
    return {
      adopted: false,
      judgments,
      excludeQuestions,
      raw: chat.content,
      note: `复用闸：pathKey=${win.pathKey} 不在候选集`,
    }
  }

  const adopted = useAttentionIo.getState().adoptReusePath({
    question: input.qNow,
    pathKey: winPath.pathKey,
    rationale: win.rationale,
    queryKey: input.queryKey,
  })
  if (!adopted) {
    return {
      adopted: false,
      judgments,
      excludeQuestions,
      raw: chat.content,
      note: `复用闸判可复用但落账失败 · path=${winPath.pathKey}`,
    }
  }

  return {
    adopted: true,
    queryKey: adopted.queryKey,
    reuseKey: adopted.reuseKey,
    pathKey: adopted.pathKey,
    oldQueryKey: adopted.oldQueryKey,
    inferKeys: adopted.inferKeys,
    prospectKeys: adopted.prospectKeys,
    judgments,
    excludeQuestions: [],
    raw: chat.content,
    note: `复用采纳 · path=${winPath.pathKey} · ${adopted.queryKey} → ${adopted.reuseKey}`,
  }
}

