  pkg: LetterDeskPackage
  bookIndex: BookIndex
  docId: string
  keys: ExpandedKey[]
  seeds: ThinSeed[]
  excludeQuestions?: Array<{ queryKey: string; qText: string }>
  excludeInfers?: Array<{ inferKey: string; rationale: string }>
  queryKey?: string
  onProgress?: (msg: string) => void
}): Promise<{ part: string; note: string }> {
