/**
 * KeyDecisionState — door-level briefs (小抄) keyed by A1 bookKey.
 * Handbook: brief is task fill on the door; NOT written into BookIndex.
 *
 * briefKey = 写信台 peek 落账微动作铸键（方案 B）。
 * contentFingerprint = 正文副索引，不当门牌。
 */

import {
  contentFingerprint,
  newSettleActionId,
  mintInstanceKey,
} from './settleMint'

export type SuggestAction = 'open' | 'defer' | 'reuse' | 'need_more_peek'

export interface BriefVersion {
  brief: string
  suggestAction: SuggestAction
  /** 该版 brief 的实例门牌（settle） */
  briefKey: string
  /** 正文副索引 */
  contentFingerprint?: string
  actionId?: string
  settleActionId?: string
  taskId?: string
  at: number
  excerptPreviewHash?: string
}

export interface KeyDecisionEntry {
  key: string
  /** Hot tip for next open-door decision (rolled) */
  decisionBrief: string
  suggestAction: SuggestAction
  /** brief 实例门牌（方案 B settle） */
  briefKey: string
  /** 正文副索引（fp_*）；仅「像不像」，不当可调取门牌 */
  contentFingerprint: string
  settleActionId: string
  updatedAt: number
  lastActionId?: string
  lastTaskId?: string
  /** Append-only audit (not default WM input) */
  history: BriefVersion[]
}

export interface KeyDecisionStore {
  docId: string
  byKey: Record<string, KeyDecisionEntry>
  updatedAt: number
}

const storeByDoc = new Map<string, KeyDecisionStore>()

/**
 * @deprecated 名称易误解。现为正文副索引 fp_*。
 * 新代码请用 contentFingerprint；门牌请用 entry.briefKey。
 */
export function briefContentHash(
  brief: string,
  suggestAction: SuggestAction,
): string {
  return contentFingerprint(`${suggestAction}\0${brief.trim()}`)
}

export function emptyKeyDecisionStore(docId: string): KeyDecisionStore {
  return { docId, byKey: {}, updatedAt: Date.now() }
}

export function getKeyDecisionStore(docId: string): KeyDecisionStore {
  let s = storeByDoc.get(docId)
  if (!s) {
    s = emptyKeyDecisionStore(docId)
    storeByDoc.set(docId, s)
  }
  return s
}

export function saveKeyDecisionStore(store: KeyDecisionStore): void {
  store.updatedAt = Date.now()
  storeByDoc.set(store.docId, store)
}

export function getDoorEntry(
  docId: string,
  key: string,
): KeyDecisionEntry | null {
  return getKeyDecisionStore(docId).byKey[key] ?? null
}

/** Roll hot tip; append previous hot tip into history. 每次落账铸新 briefKey。 */
export function rollDoorBrief(input: {
  docId: string
  key: string
  decisionBrief: string
  suggestAction: SuggestAction
  actionId?: string
  taskId?: string
  excerptPreviewHash?: string
  maxHistory?: number
  /** 若调用方已有 settle，可传入；否则台内现铸 */
  settleActionId?: string
}): KeyDecisionEntry {
  const store = getKeyDecisionStore(input.docId)
  const prev = store.byKey[input.key]
  const settleActionId =
    input.settleActionId ||
    input.actionId ||
    newSettleActionId('peek')
  const briefKey = mintInstanceKey('brief', settleActionId)
  const fingerprint = contentFingerprint(
    `${input.suggestAction}\0${input.decisionBrief.trim()}`,
  )
  const now = Date.now()
  const history = [...(prev?.history ?? [])]
  if (prev && prev.decisionBrief.trim()) {
    history.push({
      brief: prev.decisionBrief,
      suggestAction: prev.suggestAction,
      briefKey: prev.briefKey,
      contentFingerprint: prev.contentFingerprint,
      actionId: prev.lastActionId,
      settleActionId: prev.settleActionId,
      taskId: prev.lastTaskId,
      at: prev.updatedAt,
    })
  }
  const maxH = input.maxHistory ?? 12
  const trimmed = history.slice(-maxH)
  const entry: KeyDecisionEntry = {
    key: input.key,
    decisionBrief: input.decisionBrief.trim(),
    suggestAction: input.suggestAction,
    briefKey,
    contentFingerprint: fingerprint,
    settleActionId,
    updatedAt: now,
    lastActionId: input.actionId ?? settleActionId,
    lastTaskId: input.taskId,
    history: trimmed,
  }
  store.byKey[input.key] = entry
  saveKeyDecisionStore(store)
  return entry
}

export function doorsForKeys(
  docId: string,
  keys: ReadonlyArray<string>,
): KeyDecisionEntry[] {
  const store = getKeyDecisionStore(docId)
  return keys
    .map((k) => store.byKey[k])
    .filter((e): e is KeyDecisionEntry => Boolean(e))
}

/**
 * MasterTable 型指针：briefKey↔bookKey、head、版本；供写信台 expand 查表。
 * briefKey = settle 实例门牌，不用于选契约。
 */

import {
  getDoorEntry,
  getKeyDecisionStore,
  type KeyDecisionEntry,
} from './keyDecisionState'

export function mapBookToHeadBrief(
  docId: string,
  bookKey: string,
): { briefKey: string; brief: string; entry: KeyDecisionEntry } | null {
  const entry = getDoorEntry(docId, bookKey)
  if (!entry?.briefKey || !entry.decisionBrief.trim()) return null
  return {
    briefKey: entry.briefKey,
    brief: entry.decisionBrief,
    entry,
  }
}

/** briefKey（settle 实例）→ 挂靠 bookKey */
export function mapBriefToBook(
  docId: string,
  briefKey: string,
): { bookKey: string; brief: string; entry: KeyDecisionEntry } | null {
  const store = getKeyDecisionStore(docId)
  for (const [bookKey, entry] of Object.entries(store.byKey)) {
    if (entry.briefKey === briefKey) {
      return { bookKey, brief: entry.decisionBrief, entry }
    }
    for (const h of entry.history) {
      if (h.briefKey === briefKey) {
        return { bookKey, brief: h.brief, entry }
      }
    }
  }
  return null
}

export function listBriefVersionsOnDoor(
  docId: string,
  bookKey: string,
): Array<{ briefKey: string; brief: string; isHead: boolean }> {
  const entry = getDoorEntry(docId, bookKey)
  if (!entry) return []
  const out: Array<{ briefKey: string; brief: string; isHead: boolean }> = []
  if (entry.briefKey && entry.decisionBrief.trim()) {
    out.push({
      briefKey: entry.briefKey,
      brief: entry.decisionBrief,
      isHead: true,
    })
  }
  for (let i = entry.history.length - 1; i >= 0; i--) {
    const h = entry.history[i]!
    out.push({
      briefKey: h.briefKey,
      brief: h.brief,
      isHead: false,
    })
  }
  return out
}

/** 门是否已有贴（peek 门况） */
export function doorHasBrief(docId: string, bookKey: string): boolean {
  return mapBookToHeadBrief(docId, bookKey) !== null
}

/** 本任务 MasterTable 是否已有任意 head brief（写信台确定性） */
export function docHasAnyBrief(docId: string): boolean {
  const store = getKeyDecisionStore(docId)
  for (const entry of Object.values(store.byKey)) {
    if (entry.briefKey && entry.decisionBrief.trim()) return true
  }
  return false
}

/** 本任务全部 head brief（压滚材料） */
export function listAllHeadBriefs(docId: string): Array<{
  bookKey: string
  briefKey: string
  brief: string
}> {
  const store = getKeyDecisionStore(docId)
  const out: Array<{ bookKey: string; briefKey: string; brief: string }> = []
  for (const [bookKey, entry] of Object.entries(store.byKey)) {
    if (!entry.briefKey || !entry.decisionBrief.trim()) continue
    out.push({
      bookKey,
      briefKey: entry.briefKey,
      brief: entry.decisionBrief,
    })
  }
  return out
}

