function sid(): string {
  return `att_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`
}

/**
 * 默认监督：同 queryKey 下，infer.bookKeys 与 prospect.brief→book 有交集则匹配落 path。
 * 每人一对最多匹配一次；剩余未匹配的 infer 不硬造 path。
 */
function autoMatchPathsForQuery(
  get: () => AttentionIoState,
  queryKey: string,
): string[] {
  const s = get()
  const inferEdges = s.inferEdges.filter((e) => e.queryKey === queryKey)
  const prospects = s.prospects.filter((p) => p.queryKey === queryKey)
  if (inferEdges.length === 0 || prospects.length === 0) return []

  const usedProspects = new Set<string>()
  const matches: Array<{ inferKey: string; prospectKey: string }> = []

  for (const edge of inferEdges) {
    const books = new Set(edge.bookKeys)
    let hit: ProspectRecord | null = null
    for (const p of prospects) {
      if (usedProspects.has(p.prospectKey)) continue
      // briefKey 本身不带 book；用 Δ 边 / questionToBrief 反查：
      // 若 prospect 的 brief 曾作为该 infer 材料门上的贴，则算匹配。
      const briefOnBooks = s.edges.some(
        (e) => e.toKey === p.briefKey && books.has(e.fromKey),
      )
      const qBriefs = s.queryKeyToBriefKeys[queryKey] ?? []
      const briefKnown = qBriefs.includes(p.briefKey)
      if (briefOnBooks || (briefKnown && books.size > 0)) {
        // 优先 Δ 边命中；否则同 Q 的 prospect 按序填给尚未匹配的 infer
        if (briefOnBooks) {
          hit = p
          break
        }
        if (!hit) hit = p
      }
    }
    if (!hit) {
      // 兜底：仍有空闲 prospect 则按序配对（默认监督，非用户高亮）
      hit =
        prospects.find((p) => !usedProspects.has(p.prospectKey)) ?? null
    }
    if (!hit) continue
    usedProspects.add(hit.prospectKey)
    matches.push({ inferKey: edge.inferKey, prospectKey: hit.prospectKey })
  }

  if (matches.length === 0) return []
  return get().settlePaths({
    queryKey,
    matches: matches.map((m) => ({
      ...m,
      matchMode: 'supervise_default' as const,
    })),
  }).pathKeys
}

